from collections import deque
import json

H, W = 5, 4
piece_order = ['C','A','B','D','E','G','s1','s2','s3','s4']
sizes = {
    'C': (2,2),
    'A': (2,1), 'B': (2,1), 'D': (2,1), 'E': (2,1),
    'G': (1,2),
    's1': (1,1), 's2': (1,1), 's3': (1,1), 's4': (1,1),
}
# top-left positions, 0-based. Soldiers are distinguished internally only.
start_pos = {
    'A': (0,0), 'C': (0,1), 'B': (0,3),
    'D': (2,0), 'G': (2,1), 'E': (2,3),
    's1': (3,1), 's2': (3,2), 's3': (4,0), 's4': (4,3),
}
start = tuple(start_pos[p] for p in piece_order)
goal_c = (3,1)

def occ(state):
    grid = [[None]*W for _ in range(H)]
    for p, (r,c) in zip(piece_order, state):
        h,w = sizes[p]
        for rr in range(r, r+h):
            for cc in range(c, c+w):
                if not (0 <= rr < H and 0 <= cc < W):
                    return None
                if grid[rr][cc] is not None:
                    return None
                grid[rr][cc] = p
    return grid

def board(state):
    grid = [['.']*W for _ in range(H)]
    for p, (r,c) in zip(piece_order, state):
        h,w = sizes[p]
        ch = 'S' if p.startswith('s') else p
        for rr in range(r, r+h):
            for cc in range(c, c+w):
                grid[rr][cc] = ch
    return [''.join(row) for row in grid]

def neighbors(state):
    grid = occ(state)
    for i, p in enumerate(piece_order):
        r,c = state[i]
        h,w = sizes[p]
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc = r+dr, c+dc
            if nr < 0 or nc < 0 or nr+h > H or nc+w > W:
                continue
            ok = True
            # only need check newly covered rectangle cells, simple check whole target against occupancy by others
            for rr in range(nr, nr+h):
                for cc in range(nc, nc+w):
                    owner = grid[rr][cc]
                    if owner is not None and owner != p:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                lst = list(state)
                lst[i] = (nr,nc)
                yield tuple(lst)

def solve():
    q = deque([start])
    parent = {start: None}
    while q:
        s = q.popleft()
        if s[piece_order.index('C')] == goal_c:
            path = []
            while s is not None:
                path.append(s)
                s = parent[s]
            return list(reversed(path))
        for ns in neighbors(s):
            if ns not in parent:
                parent[ns] = s
                q.append(ns)
    return None

path = solve()
if path is None:
    raise SystemExit('No solution')
boards = [board(s) for s in path]
print('states', len(boards), 'moves', len(boards)-1)
print('first', boards[0])
print('last', boards[-1])
with open('/app/solution.json', 'w') as f:
    json.dump({'boards': boards}, f, indent=2)
