{"path":"/app/test_solution.py","content":"import json

H, W = 5, 4
INITIAL = ["ACCB", "ACCB", "DGGE", "DSSE", "S..S"]
UNIQUE_PIECES = set("ABCDEG")
ALL_CHARS = set("ABCDEGS.")
COUNTS = {
    "A": 2,
    "B": 2,
    "C": 4,
    "D": 2,
    "E": 2,
    "G": 2,
    "S": 4,
    ".": 2,
}
EXPECTED_SHAPES = {
    "A": (2, 1),
    "B": (2, 1),
    "C": (2, 2),
    "D": (2, 1),
    "E": (2, 1),
    "G": (1, 2),
}


def cells(board, ch):
    return {(r, c) for r, row in enumerate(board) for c, val in enumerate(row) if val == ch}


def assert_valid_board(board):
    assert isinstance(board, list)
    assert len(board) == H
    assert all(isinstance(row, str) and len(row) == W for row in board)
    flat = "".join(board)
    assert set(flat) <= ALL_CHARS
    for ch, count in COUNTS.items():
        assert flat.count(ch) == count, (ch, flat.count(ch), board)

    for ch, (height, width) in EXPECTED_SHAPES.items():
        coords = cells(board, ch)
        rows = [r for r, _ in coords]
        cols = [c for _, c in coords]
        assert max(rows) - min(rows) + 1 == height, (ch, board)
        assert max(cols) - min(cols) + 1 == width, (ch, board)
        assert len(coords) == height * width, (ch, board)
        expected = {
            (r, c)
            for r in range(min(rows), min(rows) + height)
            for c in range(min(cols), min(cols) + width)
        }
        assert coords == expected, (ch, board)


def translated_by_one(old_cells, new_cells):
    if old_cells == new_cells:
        return False
    old_sorted = sorted(old_cells)
    new_sorted = sorted(new_cells)
    dr = new_sorted[0][0] - old_sorted[0][0]
    dc = new_sorted[0][1] - old_sorted[0][1]
    if abs(dr) + abs(dc) != 1:
        return False
    return {(r + dr, c + dc) for r, c in old_cells} == new_cells


def unique_piece_move_is_legal(prev, cur, mover):
    for ch in UNIQUE_PIECES - {mover}:
        if cells(prev, ch) != cells(cur, ch):
            return False
    if cells(prev, "S") != cells(cur, "S"):
        return False

    old = cells(prev, mover)
    new = cells(cur, mover)
    if not translated_by_one(old, new):
        return False

    entered = new - old
    vacated = old - new
    return all(prev[r][c] == "." for r, c in entered) and all(cur[r][c] == "." for r, c in vacated)


def soldier_move_is_legal(prev, cur):
    for ch in UNIQUE_PIECES:
        if cells(prev, ch) != cells(cur, ch):
            return False
    old_s = cells(prev, "S")
    new_s = cells(cur, "S")
    removed = old_s - new_s
    added = new_s - old_s
    if len(removed) != 1 or len(added) != 1:
        return False
    (r1, c1), = removed
    (r2, c2), = added
    return abs(r1 - r2) + abs(c1 - c2) == 1 and prev[r2][c2] == "." and cur[r1][c1] == "."


def transition_is_legal(prev, cur):
    if prev == cur:
        return False
    return soldier_move_is_legal(prev, cur) or any(
        unique_piece_move_is_legal(prev, cur, mover) for mover in UNIQUE_PIECES
    )


def test_solution_json_contains_legal_solution():
    with open("/app/solution.json") as f:
        data = json.load(f)

    assert sorted(data.keys()) == ["boards"]
    boards = data["boards"]
    assert isinstance(boards, list)
    assert len(boards) > 1
    assert boards[0] == INITIAL

    for board in boards:
        assert_valid_board(board)

    for i, (prev, cur) in enumerate(zip(boards, boards[1:]), start=1):
        assert transition_is_legal(prev, cur), f"illegal transition at move {i}: {prev} -> {cur}"

    final_c = cells(boards[-1], "C")
    assert final_c == {(3, 1), (3, 2), (4, 1), (4, 2)}


if __name__ == "__main__":
    test_solution_json_contains_legal_solution()
    print("solution.json is valid")
"}

